    import requests

    edge_location = "https://api.localbooking.com/edge-location"
    headers = {
        "Authorization": "Bearer YOUR_ACCESS_TOKEN"
    }

    # Get the nearest location for the particular service
    response = requests.get(edge_location, headers=headers)
