        nearest_location = data['nearestLocation']

        # Get bookings for the service in the nearest location
        url = f"https://api.localbooking.com/booking/v3/service/{service_name}/me?edgeLocation={nearest_location}"
        response = requests.get(url, headers=headers)
        if response.status_code == 200:
            return response.json()
