export const useUpdateValue = (updateFunc) => {
  const [val, setVal] = useState({});

  const updateValue = () => (val, setVal) => {
    setVal({
      ...val,
      ...updateFunc(),
    });
  };

  useEffect(() => {
    updateValue();
  }, []);

  return useUpdateVal;
